begin;create extension if not exists pgtap with schema extensions;grant usage on schema extensions to cuevo_api;set local search_path=extensions,pg_catalog;select no_plan();
insert into app.courses(school_id,id,class_id,subject_id,created_by,title,description,status)values('10000000-0000-4000-8000-000000000001','9c100000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','43000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Prepared task course','Synthetic','PUBLISHED');
insert into app.assessments(school_id,id,course_id,created_by,title,instructions,max_score,status,assignment_state)values('10000000-0000-4000-8000-000000000001','9c110000-0000-4000-8000-000000000001','9c100000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Private preparation','Draft task',10,'DRAFT','CLOSED');
set local role cuevo_api;select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
select is((select count(*)from app.assessments where id='9c110000-0000-4000-8000-000000000001'),0::bigint,'Learner cannot enumerate a prepared draft');
select throws_ok($$select internal.create_learning_submission('9c110000-0000-4000-8000-000000000001','Premature work')$$,'22023',null,'Draft cannot accept a learner source');
select throws_ok($$select internal.read_assessment_rubric_identity('10000000-0000-4000-8000-000000000001','9c110000-0000-4000-8000-000000000001')$$,'42501',null,'Private draft metadata cannot bypass enumeration');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select throws_ok($$select internal.publish_prepared_assessment('9c110000-0000-4000-8000-000000000001',1,1,1)$$,'22023',null,'Unconfigured draft publication requires review');
select lives_ok($$select internal.prepare_assessment('9c110000-0000-4000-8000-000000000001','Reviewed task','Reviewed instructions',null,10,'61000000-0000-4000-8000-000000000001',null,1)$$,'Unused draft can be edited and linked to an approved objective');
select throws_ok($$select internal.publish_prepared_assessment('9c110000-0000-4000-8000-000000000001',1,2,1)$$,'22023',null,'Stale draft version denies publication');
select lives_ok($$select internal.publish_prepared_assessment('9c110000-0000-4000-8000-000000000001',2,2,1)$$,'Reviewed exact draft versions publish deliberately');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
select is((select count(*)from app.assessments where id='9c110000-0000-4000-8000-000000000001'),1::bigint,'Published task becomes available to the enrolled learner');
select lives_ok($$select internal.create_learning_submission('9c110000-0000-4000-8000-000000000001','Reviewed task source')$$,'Published task accepts one immutable learner source');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select throws_ok($$select internal.prepare_assessment('9c110000-0000-4000-8000-000000000001','Changed used task','Changed source',null,10,'61000000-0000-4000-8000-000000000001',null,3)$$,'22023',null,'Published consumed task cannot be silently edited');
reset role;
select ok(not has_function_privilege('authenticated','internal.prepare_assessment(uuid,text,text,timestamptz,numeric,uuid,uuid,integer)','EXECUTE'),'Browser cannot edit task metadata through a private function');
select ok(not has_function_privilege('cuevo_worker','internal.publish_prepared_assessment(uuid,integer,integer,integer)','EXECUTE'),'Worker cannot publish an assessment');
select*from finish();rollback;
